"use server";

import {redirect} from "next/navigation";
import {headers} from "next/headers";
import {auth} from "@/lib/auth";
import {getSessionOnce} from "@/lib/session/sessionCache";
import {createStripeCheckout} from "@/lib/Stripe/orders";

type CreateCheckoutActionInput = {
  shippingAddressId: string;
  billingAddressId: string;
};

export async function createCheckoutAction({
  shippingAddressId,
  billingAddressId,
}: CreateCheckoutActionInput) {
  const hdrs = await headers();
  const session = await getSessionOnce({headers: hdrs});

  if (!session?.user?.id) {
    throw new Error("Not authenticated");
  }

  // Call the server API to create the order and Stripe session so the
  // server can read cookies and session headers reliably.
  const res = await fetch("/api/stripe/checkout/create-session", {
    method: "POST",
    credentials: "same-origin",
    headers: {"Content-Type": "application/json"},
    body: JSON.stringify({
      billingId: billingAddressId,
      shippingId: shippingAddressId,
    }),
  });

  const json = await res.json();
  if (!res.ok) {
    throw new Error(json?.error || "Failed to create checkout session");
  }

  redirect(json.url as string);
}

import {cookies, headers} from "next/headers";
import prisma from "@/lib/prisma";
import {auth} from "@/lib/auth/auth";
import {getSessionOnce} from "@/lib/session/sessionCache";
import type {
  Cart,
  CartItem,
  Option,
  Product,
  Variant,
} from "@/generated/prisma/browser";

type CartWithItems = Cart & {
  items: (CartItem & {
    option:
      | (Option & {
          variant?: (Variant & {product?: Product | null}) | null;
        })
      | null;
  })[];
};

const cartInclude = {
  items: {
    orderBy: {createdAt: "asc"},
    include: {
      option: {
        include: {
          variant: {
            include: {
              product: true,
            },
          },
        },
      },
    },
  },
} as const;

export async function getCart(): Promise<CartWithItems | null> {
  const hdrs = await headers();
  const headerObj = Object.fromEntries(hdrs.entries()) as Record<
    string,
    string
  >;
  const session = await getSessionOnce({headers: headerObj});

  const userId = session?.user?.id ?? null;

  const cookieStore = cookies();
  const cartId = (await cookieStore).get("cartId")?.value ?? null;

  if (userId) {
    const cart = await prisma.cart.findFirst({
      where: {
        userId,
        status: "ACTIVE",
      },
      include: cartInclude,
    });

    return cart as CartWithItems | null;
  }

  if (cartId) {
    const cart = await prisma.cart.findUnique({
      where: {id: cartId},
      include: cartInclude,
    });

    if (cart?.status === "ACTIVE") {
      return cart as CartWithItems;
    }
  }

  return null;
}

import {notFound} from "next/navigation";
import {getProductsBySlug} from "@/actions/products";
import {getAllCategories} from "@/actions/categories";
import {convertDecimalToNumber} from "@/helpers";
import {getCart} from "@/app/(root)/cart/actions/getCarts";
import {ProductWithCategoryAndVariants} from "@/types/product/product";
import {Category} from "@/types/category/category";
import ProductDetail from "@/components/Product/ProductDetail";
import prisma from "@/lib/prisma";
import {ensureSession} from "@/acl/acl";
import Breadcrumbs from "@/components/shared/beardcrumbs/Breadcrumbs";
// import sleep from "@/helpers/products/sleep";

const ProductPage = async ({params}: {params: Promise<{slug: string}>}) => {
  const {slug} = await params;
  const product = await getProductsBySlug(slug);
  const safeProduct = product
    ? (convertDecimalToNumber(
        product,
      ) as unknown as ProductWithCategoryAndVariants)
    : null;

  if (!safeProduct) {
    notFound();
  }

  // Build full category path by walking parentId chain so breadcrumbs link
  // to /search/parent/.../child instead of only the child slug.
  const allCategories = await getAllCategories();
  const map = new Map<string, Category>();
  for (const c of allCategories) map.set(c.id, c);

  function buildPath(cat: Category | undefined | null) {
    if (!cat) return "";
    const segments: string[] = [];
    let cur: Category | null | undefined = cat;
    while (cur) {
      if (cur.slug) segments.push(cur.slug);
      if (!cur.parentId) break;
      cur = map.get(cur.parentId) ?? null;
    }
    return segments.reverse().join("/");
  }

  const categoryPath = buildPath(map.get(safeProduct.category.id) ?? null);

  const breadcrumbsItems = [
    {label: "Products", href: "/"},
    {label: safeProduct.category.name, href: `/search/${categoryPath}`},
    {
      label: safeProduct.name,
      href: `/product/${safeProduct.slug}`,
      active: true,
    },
  ];
  // await sleep(4000); // Simulate loading delay

  // Load cart server-side and pass as initial prop to the client component.
  const cart = await getCart();
  const serializableCart = cart ? convertDecimalToNumber(cart) : null;

  // Determine whether this product is already in the user's wishlist so the
  // client component can render the initial state without an extra request.
  let initialInWishlist: boolean | undefined = undefined;
  try {
    const session = await ensureSession();
    const userId = session?.user?.id;
    if (userId) {
      const wishlist = await prisma.wishlist.findUnique({
        where: {userId},
        include: {items: {select: {productId: true}}},
      });
      initialInWishlist = Boolean(
        wishlist?.items?.some(
          (it: {productId: string}) => it.productId === safeProduct.id,
        ),
      );
    }
  } catch (e) {
    // ignore and leave undefined so client may fallback to fetching if needed
    initialInWishlist = undefined;
  }

  return (
    <div className="mx-auto max-w-[95vw] p-5">
      <Breadcrumbs items={breadcrumbsItems} />
      <ProductDetail
        product={safeProduct}
        initialCart={serializableCart}
        initialInWishlist={initialInWishlist}
      />
    </div>
  );
};

export default ProductPage;

import {NextResponse} from "next/server";
import {ensureAndRequire} from "@/acl/acl";
import {createNewsletterCampaign} from "@/lib/resend/campaign-services";
import prisma from "@/lib/prisma";

export async function POST(request: Request) {
  try {
    // Server-side auth: require admin permission
    await ensureAndRequire(undefined, "admin:access");

    const body = await request.json();

    // Validate required fields
    if (
      typeof body.name !== "string" ||
      typeof body.subject !== "string" ||
      typeof body.html !== "string"
    ) {
      return NextResponse.json(
        {error: "Ungültige Newsletter-Daten"},
        {status: 400},
      );
    }

    const segmentId = process.env.RESEND_NEWSLETTER_SEGMENT_ID;
    if (!segmentId) {
      return NextResponse.json(
        {error: "RESEND_NEWSLETTER_SEGMENT_ID fehlt auf dem Server"},
        {status: 500},
      );
    }

    const campaign = await createNewsletterCampaign({
      name: body.name,
      subject: body.subject,
      html: body.html,
      text: typeof body.text === "string" ? body.text : undefined,
      segmentId,
    });

    return NextResponse.json({success: true, campaign}, {status: 201});
  } catch (error) {
    console.error("create newsletter failed", error);
    const message = error instanceof Error ? error.message : "Serverfehler";
    // Wenn der Abmeldelink fehlt, ist das ein Client-Fehler (400)
    if (
      message.includes("Resend-Abmeldelink") ||
      message.includes("RESEND_UNSUBSCRIBE_URL")
    ) {
      return NextResponse.json({error: message}, {status: 400});
    }

    return NextResponse.json({error: message}, {status: 500});
  }
}

export async function GET(request: Request) {
  try {
    await ensureAndRequire(undefined, "admin:access");

    const campaigns = await prisma.newsletterCampaign.findMany({
      orderBy: {createdAt: "desc"},
    });

    return NextResponse.json({success: true, campaigns});
  } catch (error) {
    console.error("list newsletters failed", error);
    return NextResponse.json(
      {error: error instanceof Error ? error.message : "Serverfehler"},
      {status: 500},
    );
  }
}

import {auth, type Session} from "@/lib/auth";
import {getSessionOnce} from "@/lib/session/sessionCache";
import {mergeAnonymousCartIntoUserCart} from "@/lib/cart/mergeAnonymousCartIntoUserCart";
import {NextRequest, NextResponse} from "next/server";
import prisma from "@/lib/prisma";

export async function GET(request: NextRequest) {
  // (debug logs removed) - post-login route runs merge server-side
  // Default target if nothing else applies
  let targetUrl = "/";
  let session: Session | null = null;
  try {
    // Use incoming request headers to resolve the correct session
    session = await getSessionOnce({
      headers: request.headers as Headers,
    });
    const userId = session?.user?.id;

    if (userId) {
      const result = await mergeAnonymousCartIntoUserCart(userId);
      // log merge result for debugging (remove this log after troubleshooting)
      try {
        if (!result) {
          console.log(
            `/api/auth/post-login: no guest cart to merge for user ${userId}`,
          );
        } else {
          console.log(
            `/api/auth/post-login: mergedCount=${result.mergedCount} warnings=${JSON.stringify(
              result.warnings,
            )} for user ${userId}`,
          );
        }
      } catch (e) {
        console.warn("Error logging merge result", e);
      }

      const role = (session as Session)?.user?.role as string | undefined;
      if (role === "user") {
        const params = new URLSearchParams();
        if (result?.warnings && result.warnings.length > 0) {
          params.set("cartWarnings", "true");
        }
        targetUrl = params.toString()
          ? `/login-verified?${params.toString()}`
          : `/login-verified`;
      } else {
        if (result?.warnings && result.warnings.length > 0) {
          const params = new URLSearchParams();
          params.set("cartWarnings", "true");
          targetUrl = `/cart?${params.toString()}`;
        } else {
          targetUrl = "/";
        }
      }
    }
  } catch (error) {
    console.error("Fehler beim Post-Login Merge:", error);
    // fallthrough to redirect to default target
  }

  // If we have a user cart, set cartId cookie to point to it so subsequent requests use the user cart
  try {
    const userCart = await prisma.cart.findFirst({
      where: {userId: session?.user?.id},
    });
    if (userCart) {
      const absolute = new URL(targetUrl, request.url);
      const res = NextResponse.redirect(absolute);
      res.cookies.set("cartId", userCart.id, {
        httpOnly: true,
        sameSite: "lax",
        path: "/",
        secure: process.env.NODE_ENV === "production",
      });
      return res;
    }
  } catch (e) {
    console.warn("post-login: failed to set user cart cookie", e);
  }

  return NextResponse.redirect(new URL(targetUrl, request.url));
}

"use server";

import {prisma} from "@/lib/prisma";
import type {Prisma} from "@/generated/prisma";

export async function checkSlug(payload: {
  slug: string;
  parentId?: string | null;
  excludeId?: string | undefined;
}) {
  const {slug, parentId, excludeId} = payload;
  if (!slug || typeof slug !== "string") {
    return {available: false};
  }

  const normalized = String(slug).trim().toLowerCase();
  const parent =
    parentId === null || parentId === undefined ? null : String(parentId);

  if (excludeId) {
    const existing = await prisma.category.findFirst({
      where: {parentId: parent, slug: normalized, NOT: {id: excludeId}},
      select: {id: true},
    });
    return {available: !Boolean(existing)};
  }

  const existing = await prisma.category.findFirst({
    where: {parentId: parent, slug: normalized},
    select: {id: true},
  });

  return {available: !Boolean(existing)};
}

import {ensureAndRequire} from "@/acl/acl";
import prisma from "@/lib/prisma";

// opts can be { headers } or { req } — pass through to ensureAndRequire
export async function getAllMerchants(
  opts: Parameters<typeof ensureAndRequire>[0] = {},
) {
  // require admin permission
  try {
    await ensureAndRequire(opts, "admin:read");
  } catch (_err) {
    // Permission failed — return null quietly to avoid leaking information
    return null;
  }

  // fetch merchants (adjust fields as needed)
  const merchants = await prisma.merchant.findMany({
    select: {
      id: true,
      email: true,
      name: true,
      phone: true,
      web: true,
    },
    orderBy: {createdAt: "desc"},
  });

  return merchants;
}

export default getAllMerchants;

"use client";
import {UseFormReturn, useWatch} from "react-hook-form";
import type {ProductFormData} from "@/types/product/productFormData";
import {
  FormField,
  FormItem,
  FormLabel,
  FormControl,
  FormMessage,
} from "@/components/ui/form";
import {CircleMinus, PlusCircle, ChevronDown, ChevronRight} from "lucide-react";
import {Input} from "@/components/ui/input";
import {Button} from "@/components/ui/button";
import {useRef, useState, useCallback, useEffect, useMemo} from "react";
import Image from "next/image";

export default function OptionForm({
  form,
  variantIndex,
  optionIndex,
  remove,
}: {
  form: UseFormReturn<ProductFormData>;
  variantIndex: number;
  optionIndex: number;
  remove: () => void;
}) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const images = (useWatch({
    control: form.control,
    name: `variants.${variantIndex}.options.${optionIndex}.image`,
  }) ?? []) as string[];

  // legacy `color` field removed from form; use `baseColor` and `displayColor`

  const baseColor = (useWatch({
    control: form.control,
    name: `variants.${variantIndex}.options.${optionIndex}.baseColor`,
  }) ?? "") as string;

  const displayColor = (useWatch({
    control: form.control,
    name: `variants.${variantIndex}.options.${optionIndex}.displayColor`,
  }) ?? "") as string;

  // no sync effect: server will map `baseColor`/`displayColor` into legacy `color` as needed

  const BASE_COLORS = useMemo(
    () => [
      "RED",
      "BLUE",
      "GREEN",
      "PURPLE",
      "BLACK",
      "WHITE",
      "GREY",
      "BROWN",
      "YELLOW",
      "ORANGE",
      "PINK",
      "MULTICOLOR",
      "OTHER",
    ],
    [],
  );

  const sku = (useWatch({
    control: form.control,
    name: `variants.${variantIndex}.options.${optionIndex}.sku`,
  }) ?? "") as string;

  const [skuTouched, setSkuTouched] = useState(false);
  const [isImageEmpty, setIsImageEmpty] = useState(images.length === 0);
  const [showReusePanel, setShowReusePanel] = useState(false);
  const [collapsed, setCollapsed] = useState(false);

  const getImageKey = useCallback((img: string, idx: number) => {
    return `${img.slice(-20)}${idx}`;
  }, []);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const fileArray = Array.from(files);
    const previews = await Promise.all(
      fileArray.map(
        (file) =>
          new Promise<string>((resolve) => {
            const reader = new FileReader();
            reader.onload = (ev) => resolve(ev.target?.result as string);
            reader.readAsDataURL(file);
          }),
      ),
    );

    form.setValue(
      `variants.${variantIndex}.options.${optionIndex}.image`,
      [...images, ...previews],
      {shouldDirty: true, shouldValidate: true},
    );
    setIsImageEmpty(false);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleRemoveImage = (imgIdx: number) => {
    const newImages = images.filter((_, i) => i !== imgIdx);
    form.setValue(
      `variants.${variantIndex}.options.${optionIndex}.image`,
      newImages,
      {shouldDirty: true, shouldValidate: true},
    );
    setIsImageEmpty(newImages.length === 0);
  };

  const addExistingImage = (img: string) => {
    if (!img) return;
    // avoid duplicates
    if (images.includes(img)) {
      // Image already present in this option — ignore duplicate add
      return;
    }
    form.setValue(
      `variants.${variantIndex}.options.${optionIndex}.image`,
      [...images, img],
      {shouldDirty: true, shouldValidate: true},
    );
    setIsImageEmpty(false);
  };

  type GroupedImage = {
    src: string;
    variantIndex: number;
    optionIndex: number;
  };

  type ImageGroup = {
    label: string;
    items: GroupedImage[];
  };

  const otherImages = useMemo((): ImageGroup[] => {
    try {
      const variants = form.getValues("variants") as
        | ProductFormData["variants"]
        | undefined;
      if (!variants) return [];

      const groupsMap = new Map<string, Map<string, GroupedImage>>();

      variants.forEach((v, vIdx) => {
        (v.options || []).forEach((opt, oIdx) => {
          if (vIdx === variantIndex && oIdx === optionIndex) return;
          const label = `Size ${v.size || v.id} — Option ${oIdx + 1}`;
          const inner = groupsMap.get(label) ?? new Map<string, GroupedImage>();
          (opt.image || []).forEach((img) => {
            if (typeof img === "string" && img.length > 0) {
              if (!inner.has(img)) {
                inner.set(img, {
                  src: img,
                  variantIndex: vIdx,
                  optionIndex: oIdx,
                });
              }
            }
          });
          if (inner.size > 0) groupsMap.set(label, inner);
        });
      });

      const groups: ImageGroup[] = [];
      groupsMap.forEach((map, label) => {
        groups.push({label, items: Array.from(map.values())});
      });
      return groups;
    } catch (e: unknown) {
      console.error("Error while fetching other images:", e);
      return [];
    }
  }, [form, variantIndex, optionIndex]);

  const normalizeForSku = (s: string) => {
    if (!s) return "";
    const noDiacritics = s.normalize("NFD").replace(/\p{Diacritic}/gu, "");
    return noDiacritics
      .replace(/[^a-z0-9]+/gi, "-")
      .replace(/^-+|-+$/g, "")
      .replace(/-+/g, "-")
      .toUpperCase();
  };

  const generateSku = (
    productSlug: string | undefined,
    variantSize: string | undefined,
    colorStr: string | undefined,
    optIndex: number,
  ) => {
    const parts: string[] = [];
    if (productSlug) parts.push(normalizeForSku(productSlug));
    if (variantSize) parts.push(normalizeForSku(variantSize));
    if (colorStr) parts.push(normalizeForSku(colorStr));
    parts.push(String(optIndex + 1).padStart(2, "0"));
    return parts.join("-");
  };

  useEffect(() => {
    try {
      if (skuTouched) return;
      if (sku && sku.trim().length > 0) return;
      const productSlug = form.getValues("slug");
      const variantSize = form.getValues(`variants.${variantIndex}.size`);
      const effectiveColor =
        displayColor && displayColor.trim().length > 0
          ? displayColor
          : baseColor && baseColor.trim().length > 0
            ? baseColor
            : undefined;
      const gen = generateSku(
        productSlug,
        variantSize,
        effectiveColor,
        optionIndex,
      );
      if (gen) {
        form.setValue(
          `variants.${variantIndex}.options.${optionIndex}.sku`,
          gen,
          {shouldDirty: true, shouldValidate: true},
        );
      }
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      console.warn("SKU generation failed", msg);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [baseColor, displayColor, variantIndex, optionIndex, form, skuTouched]);

  return (
    <div className="flex flex-wrap gap-2 mb-2 p-2 relative">
      <span
        onClick={() => setCollapsed((s) => !s)}
        className="flex items-center justify-center w-10 h-10 bg-amber-600 rounded-full absolute -top-16 left-0 p-2"
      >
        {collapsed ? (
          <ChevronRight className="size-6" />
        ) : (
          <ChevronRight className="size-6" />
        )}{" "}
      </span>
      <FormField
        control={form.control}
        name={`variants.${variantIndex}.options.${optionIndex}.image`}
        render={() => (
          <FormItem className="py-3 w-full">
            <FormLabel
              className={`font-thin text-[0.6rem] md:text-lg ${
                isImageEmpty ? "text-destructive" : "text-foreground"
              }`}
            >
              Images (at least one!!)
            </FormLabel>
            <FormControl>
              <div className="flex flex-col gap-2">
                <input
                  type="file"
                  accept="image/*"
                  multiple
                  ref={fileInputRef}
                  className="hidden"
                  onChange={handleImageUpload}
                />
                <div className="flex gap-2 items-center">
                  <Button
                    type="button"
                    className="flex items-center gap-5 text-sm md:text-md bg-primary-foreground/20 hover:bg-primary-foreground/30"
                    onClick={() => fileInputRef.current?.click()}
                  >
                    Bilder hochladen <PlusCircle className="size-4 ml-2" />
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    className="flex items-center gap-2 text-sm md:text-md"
                    onClick={() => setShowReusePanel((s) => !s)}
                  >
                    Use existing
                  </Button>
                </div>

                {showReusePanel && (
                  <div className="mt-2 p-2 border rounded bg-muted/10 max-w-full overflow-auto">
                    <p className="text-xs mb-2 text-muted-foreground">
                      Other images (click to add)
                    </p>
                    {otherImages && otherImages.length > 0 ? (
                      <div className="flex flex-col gap-3">
                        {otherImages.map((group) => (
                          <div key={group.label} className="">
                            <div className="text-xs font-semibold text-muted-foreground mb-1">
                              {group.label}
                            </div>
                            <div className="flex gap-2 flex-wrap">
                              {group.items.map((it, i) => (
                                <button
                                  key={it.src + String(i)}
                                  type="button"
                                  onClick={() => addExistingImage(it.src)}
                                  className="relative"
                                  title={`Add image from ${group.label}`}
                                >
                                  {it.src.startsWith("data:") ? (
                                    // use plain img for data URLs to avoid next/image optimization issues
                                    // eslint-disable-next-line @next/next/no-img-element
                                    <img
                                      src={it.src}
                                      alt={`existing-${i}`}
                                      width={60}
                                      height={60}
                                      className="rounded border object-cover"
                                    />
                                  ) : (
                                    <Image
                                      src={it.src}
                                      alt={`existing-${i}`}
                                      width={60}
                                      height={60}
                                      className="rounded border object-cover"
                                    />
                                  )}
                                </button>
                              ))}
                            </div>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="text-sm text-muted-foreground">
                        No existing uploaded images found for other options.
                      </div>
                    )}
                  </div>
                )}
              </div>
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
      {!collapsed && (
        <>
          <div className="w-full flex flex-col lg:flex-row items-center gap-10">
            <FormField
              control={form.control}
              name={`variants.${variantIndex}.options.${optionIndex}.baseColor`}
              render={({field}) => (
                <FormItem className="py-3 w-full">
                  <FormLabel
                    className={`font-thin text-[0.6rem] md:text-lg ${
                      form.formState.errors.variants?.[variantIndex]?.options?.[
                        optionIndex
                      ]?.baseColor
                        ? "text-destructive"
                        : "text-foreground"
                    }`}
                  >
                    Base Color
                  </FormLabel>
                  <FormControl>
                    <select
                      disabled={form.formState.isSubmitting}
                      {...field}
                      value={field.value ?? ""}
                      onChange={(e) => field.onChange(e.target.value)}
                      className="w-full border-b-[0.3px] border-border focus-visible:underlined py-6 text-[0.6rem] md:text-lg"
                    >
                      <option className="bg-background " value="">
                        Select color
                      </option>
                      {BASE_COLORS.map((c) => (
                        <option className="bg-background " key={c} value={c}>
                          {c}
                        </option>
                      ))}
                    </select>
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            {/* Display color (marketing label) — stored to `displayColor` and synced into `color` */}
            <FormField
              control={form.control}
