"use client";
import React, {useEffect, useState} from "react";
import {isDisposableEmail} from "@/lib/disposable-email-check";
import {Input} from "../ui/input";
import {Gift} from "lucide-react";
import {Button} from "../ui/button";
import Link from "next/link";
import SuccessToast from "@/components/shared/customToast/SuccessToast";
import ErrorToast from "@/components/shared/customToast/ErrorToast";
import {Span} from "next/dist/trace";

type Props = {
  onSuccess?: () => void;
  title?: string | null; // if null => hide title; if undefined => show default
};

export default function NewsletterForm({onSuccess, title}: Props) {
  const [email, setEmail] = useState("");
  const [consent, setConsent] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [emailError, setEmailError] = useState<string | null>(null);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setMessage(null);
    // ensure basic checks
    if (!email || !consent) {
      setMessage("Bitte E-Mail eingeben und Einwilligung akzeptieren.");
      return;
    }

    // if client-side validation flagged an error, show unified message
    if (emailError) {
      setMessage("Email Validierung fehlgeschlagen");
      return;
    }
    setLoading(true);
    try {
      const fd = new FormData();
      fd.set("email", email);
      fd.set("consent", consent ? "on" : "off");
      const res = await fetch("/api/resend/subscribe", {
        method: "POST",
        body: fd,
      });
      const json = await res.json();
      if (json?.success) {
        setMessage(json.message || "Bitte prüfe dein Postfach.");
        setEmail("");
        setConsent(false);
        onSuccess?.();
      } else {
        const serverMsg = String(json?.message ?? "");
        if (
          serverMsg.includes("Ungültige E-Mail") ||
          serverMsg.includes("Temporäre E‑Mail") ||
          serverMsg.includes("Anfragen von deiner IP") ||
          serverMsg.includes("Eingaben prüfen")
        ) {
          setMessage("Email Validierung fehlgeschlagen");
        } else {
          setMessage(serverMsg || "Fehler bei der Anmeldung.");
        }
      }
    } catch (err) {
      console.error("Error in newsletter form submission:", err);
      setMessage("Netzwerkfehler.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    if (!email) {
      setEmailError(null);
      return;
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      setEmailError("Ungültiges Format");
      return;
    }
    if (isDisposableEmail(email)) {
      setEmailError("Disposable E-Mail nicht erlaubt");
      return;
    }
    setEmailError(null);
  }, [email]);

  return (
    <div className="relative flex flex-col items-center justify-center gap-5 bg-card/40 rounded-lg border-[0.3px] border-foreground/10 h-128 overflow-hidden w-full p-4">
      <h1 className="flex items-center justify-center absolute -top-8 -left-8 md:-top-12 md:-left-8 font-bold bg-brand-sage rounded-full p-3 md:p-4 lg:p-6 aspect-square">
        <span className="text-3xl md:text-4xl font-bold mt-6 ml-6">5,0 %</span>
      </h1>

      {title === null ? null : (
        <div className="font-normal text-left text-md md:text-xl max-w-[75%]">
          {typeof title === "string" ? (
            <span className="font-normal text-left text-md md:text-xl">
              {title}
            </span>
          ) : (
            <span className="font-normal text-left text-md md:text-xl">
              Melde dich für unseren Newsletter an! Profitiere von exklusiven
              Angeboten, Neuigkeiten und spannenden Inhalten direkt in deinem
              Posteingang. Jetzt 5,0 % sichern!
            </span>
          )}
        </div>
      )}

      <hr className="w-full border-foreground/10 my-4" />

      <form
        onSubmit={handleSubmit}
        className="backdrop-blur-xs w-full md:max-w-3/4"
      >
        <div className="flex items-start justify-start gap-6">
          <Input
            aria-label="E-Mail"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="Deine E-Mail"
            className="w-full border-b-[0.3px] border-border focus-visible:underlined py-6 text-[0.6rem] md:text-lg"
            required
          />
          <Button
            type="submit"
            disabled={loading || !!emailError || !consent}
            className="px-4 py-6 bg-primary text-white rounded disabled:opacity-50"
          >
            {loading ? "..." : "Anmelden"}
          </Button>
        </div>
        <label className="flex items-center gap-4 mt-8 text-sm">
          <input
            type="checkbox"
            className="w-4 h-4 bg-primary cursor-pointer"
            checked={consent}
            onChange={(e) => setConsent(e.target.checked)}
            required
          />
          <span className="text-foreground">
            Ich möchte den Newsletter erhalten und stimme der
            <Link
              href="/datenschutz"
              className="text-destructive underlined px-1"
            >
              Datenschutzerklärung
            </Link>
            zu.
          </span>
        </label>
        <div className="my-2 flex flex-col justify-center">
          {emailError ? (
            <ErrorToast
              message={emailError}
              duration={4000}
              onClose={() => setEmailError(null)}
            />
          ) : null}
        </div>
        {message && (
          <SuccessToast
            message={message}
            duration={4000}
            onClose={() => setMessage(null)}
          />
        )}
      </form>
      <Gift className="absolute -bottom-6 -right-6 md:-bottom-12 md:-right-12 text-primary size-24 md:size-42" />
    </div>
  );
}

import {AlertOctagon} from "lucide-react";
import React, {useEffect} from "react";

interface ErrorToastProps {
  message?: string;
  /** milliseconds until the toast auto-closes (defaults to 4000) */
  duration?: number;
  /** called when the toast should be closed (parent should clear the message) */
  onClose?: () => void;
}

const ErrorToast = ({message, duration = 4000, onClose}: ErrorToastProps) => {
  useEffect(() => {
    if (!message) return;
    if (!onClose) return;
    const t = setTimeout(() => {
      try {
        onClose();
      } catch (e) {
        // ignore
      }
    }, duration);
    return () => clearTimeout(t);
  }, [message, duration, onClose]);

  if (!message) return null;

  return (
    <div className="flex items-start bg-destructive w-full rounded-md text-white text-center p-2 mb-5">
      <span className="flex items-center justify-center gap-2">
        <AlertOctagon width={20} height={20} />
        {message}
      </span>
    </div>
  );
};

export default ErrorToast;

export async function mergeGuestWishlist(): Promise<{
  ok: boolean;
  merged?: boolean;
  error?: string;
}> {
  try {
    if (typeof window === "undefined") return {ok: false, error: "no-window"};

    const raw = localStorage.getItem("guest_wishlist");
    if (!raw) return {ok: true, merged: false};

    let productIds: string[] = [];
    try {
      productIds = JSON.parse(raw) as string[];
    } catch (e) {
      // invalid payload -> clear it
      localStorage.removeItem("guest_wishlist");
      return {ok: true, merged: false};
    }

    if (!Array.isArray(productIds) || productIds.length === 0) {
      localStorage.removeItem("guest_wishlist");
      return {ok: true, merged: false};
    }

    const res = await fetch("/api/wishlist/merge", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({productIds}),
    });

    if (!res.ok) {
      return {ok: false, error: `merge-failed:${res.status}`};
    }

    // On success clear guest wishlist
    localStorage.removeItem("guest_wishlist");
    return {ok: true, merged: true};
  } catch (err: unknown) {
    const errorMsg =
      typeof err === "string"
        ? err
        : err && typeof err === "object" && "message" in err
          ? String((err as {message?: unknown}).message ?? err)
          : String(err);
    return {ok: false, error: errorMsg};
  }
}
